				index,
				start: Number(cue?.start) || 0,
				end: Number(cue?.end) || 0,
				origText,
				simpText,
				jaSource,
				actHits,
				plotHits,
				contextHits,
				jaHits,
				jaInOrigHits,
				hasStrong: actHits.length > 0 || plotHits.length > 0 || jaHits.length > 0,
				gatedContextHits: []
